pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {FlashGovernanceArbiter} from "../src/FlashGovernanceArbiter.sol";

contract InvMutTest is Test {
    FlashGovernanceArbiter c;
    function setUp() public { c = new FlashGovernanceArbiter(address(new __InvMutHandleStub())); }

    function testFuzz_property(address daoAddr, address caller) public {
        // Admissible domain: caller must be allowed by the reference's require:
        // require(DAO == address(0) || msg.sender == DAO || !configured, "EK")
        // Fresh contract: DAO == address(0), so ANY caller may call setDAO.
        vm.assume(daoAddr != address(0));
        vm.prank(caller);
        try c.setDAO(daoAddr) {} catch {}

        assertTrue(c.DAO() == daoAddr);
    }
}

